`timescale 1ns / 1ps
// Generated by pipeline/make_tasks.py (sign-off). Reference: golden/reference (falling_edge_pulse_generator__ref below).
module tb;
  reg tb_clk; integer tb_seed, tb_cyc, tb_mis, tb_perr, tb_b, tb_k, tb_ph; reg tb_started; reg [31:0] tb_r;
  reg reset;
  reg gnt;
  wire clk = tb_clk;
  wire [0:0] q0; wire [0:0] ref_q0;
  reg fp_F, fp_q0_pre, fp_gnt_prev, fp_expect; time fp_tfall;
  falling_edge_pulse_generator dut (.reset(reset), .gnt(gnt), .clk(clk), .q0(q0));
  falling_edge_pulse_generator__ref ref_i (.reset(reset), .gnt(gnt), .clk(clk), .q0(ref_q0));
  always #5 tb_clk = ~tb_clk;
  function [31:0] tb_rand(input integer dummy); begin tb_rand = $random(tb_seed); end endfunction
  // flit: type in [30:29], VC in [28:27], destination row/column 0..3 in [7:4]/[3:0]
  function [31:0] tb_flit(input integer dummy); reg [31:0] r; begin r = $random(tb_seed);
    tb_flit = {1'b0, r[30:29], r[28:27], r[26:8], 2'b00, r[5:4], 2'b00, r[1:0]}; end endfunction
  task tb_prop(input [8*64:1] msg); begin tb_perr = tb_perr + 1;
    if (tb_perr <= 15) $display("FAIL property: %0s (t=%0t)", msg, $time); end endtask
  task tb_compare; begin
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1)
      if (ref_q0[tb_b] !== 1'bx && ref_q0[tb_b] !== 1'bz && q0[tb_b] !== ref_q0[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 1;
        if (tb_mis <= 15) $display("MISMATCH (secondary, not part of the verdict) t=%0t cycle %0d: q0 = %h, expected %h", $time, tb_cyc, q0, ref_q0);
      end
  end endtask
  task tb_props; begin
    if (tb_ph == 0) begin
      if (tb_started && fp_expect && q0 !== 1'b1) tb_prop("no pulse after gnt fell");
      fp_q0_pre = q0; fp_expect = 1'b0;
    end else begin
      if (tb_started && !reset && fp_q0_pre === 1'b1 && q0 !== 1'b0) tb_prop("pulse did not end at the clk edge");
      fp_F = reset ? 1'b0 : fp_q0_pre;
    end
  end endtask
  reg [0:0] tbc_p_q0, tbc_t_q0;
  integer tbc_outs, tbc_bits;
  task tb_cov; begin
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_q0 = tbc_t_q0 | ((ref_q0 ^ tbc_p_q0) & ~(ref_q0 ^ ref_q0)); tbc_p_q0 = ref_q0;
  end endtask
  task tb_cov_report; begin tbc_outs = 0; tbc_bits = 0;
    if (|tbc_t_q0) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_q0[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    $display("INFO coverage: %0d of 1 checked outputs toggled, %0d of 1 bits", tbc_outs, tbc_bits);
  end endtask
  always @(posedge q0) if (tb_started && ($time != fp_tfall || gnt !== 1'b0)) tb_prop("q0 rose without a falling edge of gnt");
  initial begin
    tb_seed = 29; tb_clk = 0; tb_mis = 0; tb_perr = 0; tb_started = 0; tb_ph = 0; tb_k = 0;
    reset = 0; gnt = 0; reset = 1;
    tbc_t_q0 = 0; tbc_p_q0 = 0;
    for (tb_cyc = 0; tb_cyc < 5000; tb_cyc = tb_cyc + 1) begin
      @(negedge tb_clk);
      reset = (tb_cyc < 4) ? 1'b1 : (tb_rand(0) % 400 == 0);
      if (tb_rand(0) % 3 == 0) gnt = ~gnt;
      if (fp_gnt_prev === 1'b1 && gnt === 1'b0) begin fp_tfall = $time; fp_expect = !reset && fp_F === 1'b0; end
      fp_gnt_prev = gnt; if (reset) fp_F = 1'b0;
      tb_started = (tb_cyc >= 6);
      #4 tb_ph = 0; tb_compare; tb_props; if (tb_started) tb_cov;
      @(posedge tb_clk); #4 tb_ph = 1; tb_compare; tb_props; if (tb_started) tb_cov;
    end
    tb_cov_report;
    $display("INFO cycle-exact mismatches against golden/reference: %0d (secondary)", tb_mis);
    if (tb_perr == 0) $display("ALL TESTS PASSED"); else $display("FAIL: %0d property errors", tb_perr);
    $finish;
  end
endmodule

